<?php
require __DIR__.'/app/bootstrap.php';require_login();require __DIR__.'/app/layout.php';
$q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$sql="SELECT a.*,r.registration_date FROM applicants a LEFT JOIN registrations r ON r.applicant_id=a.id WHERE 1=1";$params=[];
if($q!==''){$sql.=" AND (a.applicant_no LIKE ? OR a.first_name LIKE ? OR a.last_name LIKE ? OR a.phone LIKE ? OR a.email LIKE ?)";$like='%'.$q.'%';array_push($params,$like,$like,$like,$like,$like);}
if(in_array($status,['Pending','In Review','Approved','Rejected'],true)){$sql.=' AND a.status=?';$params[]=$status;}$sql.=' ORDER BY a.created_at DESC';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
page_header('Applicants'); ?>
<div class="panel"><form class="searchbar" method="get"><label class="search-field">Search records<input name="q" value="<?=e($q)?>" placeholder="Applicant number, name, phone or email"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['Pending','In Review','Approved','Rejected'] as $s): ?><option value="<?=e($s)?>" <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select></label><button class="btn primary" type="submit">Search</button><?php if($q!==''||$status!==''): ?><a class="btn secondary" href="applicants.php">Clear</a><?php endif; ?></form><div class="panel-heading"><div><h2>Applicant records</h2><p class="muted"><?=count($rows)?> matching record(s)</p></div><a class="btn primary" href="applicant_form.php">＋ Register applicant</a></div><div class="table-wrap"><table><thead><tr><th>Applicant no.</th><th>Full name</th><th>Date of birth</th><th>District</th><th>Registered</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $a): ?><tr><td><strong><?=e($a['applicant_no'])?></strong></td><td><?=e($a['first_name'].' '.$a['last_name'])?></td><td><?=e($a['date_of_birth'])?></td><td><?=e($a['district']?:'—')?></td><td><?=e($a['registration_date']?:'—')?></td><td><span class="pill"><?=e($a['status'])?></span></td><td class="actions"><a href="applicant_view.php?id=<?=(int)$a['id']?>">View</a><a href="applicant_form.php?id=<?=(int)$a['id']?>">Edit</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7" class="empty">No matching applicants found.</td></tr><?php endif; ?></tbody></table></div></div>
<?php page_footer(); ?>
